Given a Singly linked list containing n nodes. The task is to reverse every group of k nodes in the list. If the number of nodes is not a multiple of k then left-out nodes, in the end, should be considered as a group and must be reversed.Examples: Input: head: 1 -> 2 -> 3 -> 4 -> 5 -> 6 -> NULL, k = 2 Output: head: 2 -> 1 -> 4 -> 3 -> 6 -> 5 -> NULL Explanation : Linked List is reversed in a group of size k = 2. Input: head: 1 -> 2 -> 3 -> 4 -> 5 -> 6 -> NULL, k = 4 Output: head:  4 -> 3 -> 2 -> 1 -> 6 -> 5 -> NULLExplanation : Linked List is reversed in a group of size k = 4. Approach:The idea is to use a Stack to store the nodes of the given linked list. Firstly, push the k nodes of the linked list into the stack. Now, pop the nodes one by one and keep track of the previously popped node. Point the next pointer of the prev node to the top element of the stack. Repeat this process, until we reach end of linked list.Below is the implementation of the above approach: 
            C++

    // C++ program to reverse a linked list in groups
// of given size

#include <bits/stdc++.h>
using namespace std;

class Node {
  public:
    int data;
    Node *next;

    Node(int x) {
        data = x;
        next = nullptr;
    }
};

// Function to reverse the linked list in groups
Node *reverseKGroup(Node *head, int k) {
    if (!head || k == 1) {
        return head;
    }

    stack<Node*> st; 
    Node *curr = head; 
    Node *prev = nullptr; 

    while (curr != nullptr) { 

        // Terminate the loop when either
      	// current == NULL or count >= k 
        int count = 0; 
        while (curr != nullptr && count < k) { 
            st.push(curr); 
            curr = curr->next; 
            count++; 
        } 

        // Now pop the elements from the stack one by one 
        while (!st.empty()) { 

            // If the final list has not been started yet
            if (prev == nullptr) { 
                prev = st.top(); 
                head = prev; 
                st.pop(); 
            } else { 
                prev->next = st.top(); 
                prev = prev->next; 
                st.pop(); 
            } 
        } 
    } 

    // Set the next pointer of the 
  	// last node to NULL
    prev->next = nullptr; 

    return head; 
}

void printList(Node *head) {
    Node *curr = head;
    while (curr != nullptr) {
        cout << curr->data << " ";
        curr = curr->next;
    }
    cout << endl;
}

int main() {

    // Creating a sample singly linked list:
    // 1 -> 2 -> 3 -> 4 -> 5 -> 6
    Node *head = new Node(1);
    head->next = new Node(2);
    head->next->next = new Node(3);
    head->next->next->next = new Node(4);
    head->next->next->next->next = new Node(5);
    head->next->next->next->next->next = new Node(6);

    head = reverseKGroup(head, 3);

    printList(head);

    return 0;
}


