    // Java program to reverse a linked list
// in groups of given size

import java.util.Stack;

class Node {
    int data;
    Node next;

    Node(int data) {
        this.data = data;
        this.next = null;
    }
}

// Function to reverse the linked list in groups
class GfG {
    static Node reverseKGroup(Node head, int k) {
        if (head == null || k == 1) {
            return head;
        }

        Stack<Node> st = new Stack<>();
        Node curr = head;
        Node prev = null;

        while (curr != null) {

            // Terminate the loop when either 
          	// current == null or count >= k
            int count = 0;
            while (curr != null && count < k) {
                st.push(curr);
                curr = curr.next;
                count++;
            }

            // Now pop the elements from the stack one by one
            while (!st.isEmpty()) {

                // If the final list has not been started yet
                if (prev == null) {
                    prev = st.pop();
                    head = prev;
                } else {
                    prev.next = st.pop();
                    prev = prev.next;
                }
            }
        }

        // Set the next pointer of the last node to null
        prev.next = null;

        return head;
    }

    static void printList(Node head) {
        Node curr = head;
        while (curr != null) {
            System.out.print(curr.data + " ");
            curr = curr.next;
        }
        System.out.println();
    }

    public static void main(String[] args) {

        // Creating a sample singly linked list:
        // 1 -> 2 -> 3 -> 4 -> 5 -> 6
        Node head = new Node(1);
