class Node {
    constructor(data) {
        this.data = data;
        this.next = null;
    }
}

// Function to reverse the linked list in groups
function reverseKGroup(head, k) {
    if (!head || k === 1) {
        return head;
    }

    let st = [];
    let curr = head;
    let prev = null;

    while (curr !== null) {

        // Terminate the loop when either 
        // current == null or count >= k
        let count = 0;
        while (curr !== null && count < k) {
            st.push(curr);
            curr = curr.next;
            count++;
        }

        // Now pop the elements from the stack one by one
        while (st.length > 0) {

            // If the final list has not been started yet
            if (prev === null) {
                prev = st.pop();
                head = prev;
            } else {
                prev.next = st.pop();
                prev = prev.next;
            }
        }
    }

    // Set the next pointer of the last node to null
    prev.next = null;

    return head;
}

